def find_length(binary, n): 
    diff = [0] * n 
    for i in range(n): 
        if (binary[i] == '0'): 
            diff[i] = -1
        else: 
            diff[i] = 1
    max_diff = -1
    min_sum = 0
    sum = 0
    for i in range(n): 
        sum += diff[i] 
        if (max_diff < sum - min_sum): 
            max_diff = sum - min_sum 
        if (min_sum > sum): 
            min_sum = sum 
    return max_diff
```

