def cal_electbill(units):
    # Define the base charge and unit rate
    base_charge = 200
    unit_rate = 6.5

    # Calculate the electricity bill
    if units <= 50:
        bill = base_charge + (units * unit_rate)
    elif units <= 150:
        bill = base_charge + 50 * unit_rate + (units - 50) * (unit_rate * 1.5)
    elif units <= 250:
        bill = base_charge + 50 * unit_rate + 100 * (unit_rate * 1.5) + (units - 150) * (unit_rate * 2)
    else:
        bill = base_charge + 50 * unit_rate + 100 * (unit_rate * 1.5) + 100 * (unit_rate * 2) + (units - 250) * (unit_rate * 2.5)

    # Return the calculated bill rounded to two decimal places
    return round(bill, 2)
